//+------------------------------------------------------------------+
//| Script program start function                                    |
//+------------------------------------------------------------------+
void OnStart()
  {
   //--- Define the symbol and trading parameters
   string symbol = Symbol(); // Get the current symbol
   double stopLossPips = CalculateStopLossPips(symbol, 0.01); // 1% risk
   double lotSize = CalculateLotSize(symbol, 0.01); // Calculate lot size based on risk

   //--- Check for trading availability
   if (!IsTradeAllowed())
     {
      Print("Trading is not allowed!");
      return;
     }

   //--- Example: Placing a BUY order
   MqlTradeRequest request;
   MqlTradeResult  result;
   ZeroMemory(request);

   request.action = TRADE_ACTION_DEAL;
   request.symbol = symbol;
   request.volume = lotSize;
   request.type = ORDER_TYPE_BUY;
   request.price = SymbolInfoDouble(symbol, SYMBOL_ASK);
   request.sl = request.price - stopLossPips * Point(); // BUY: SL below price
   request.tp = 0; // Optional: Take Profit
   request.deviation = 10; // Slippage allowance
   request.magic = 123456; // Magic number for your EA

   //--- Send the trade request
   if (OrderSend(request, result))
     {
      Print("Order placed successfully!");
      Print("Order Ticket: ", result.deal);
      Print("Result code: ", result.retcode);
      Print("Stop Loss in price: ", request.sl);
     }
   else
     {
      Print("Order placement failed!");
      Print("Error code: ", GetLastError());
      //Print("Error Description: ", ErrorDescription(GetLastError())); // Uncomment for more detailed error messages.  Not available directly in MQL5.  Must implement custom function.
     }
  }

//+------------------------------------------------------------------+
//| Function to calculate the Stop Loss in pips based on a percentage of balance |
//+------------------------------------------------------------------+
double CalculateStopLossPips(string symbol, double riskPercentage)
  {
   double balance = AccountInfoDouble(ACCOUNT_BALANCE);
   double accountCurrencyProfitPerPip;
   double tickValue;


   //--- Get the tick value in account currency
   tickValue = MarketInfo(symbol, MODE_TICKVALUE);

   //--- Calculate the amount of money we're willing to risk
   double riskAmount = balance * riskPercentage;

   //---  Determine the equivalent Pips based on available funds
   accountCurrencyProfitPerPip = NormalizeDouble( fabs(tickValue), Digits());

   if( accountCurrencyProfitPerPip == 0 ) {
      Print(__FUNCTION__, " : MarketInfo(MarketInfo(symbol, MODE_TICKVALUE)) = 0! Return a default stopLoss value.");
      return 50; // Return 50 if tickValue cannot be determined
   }

   double stopLossPips = riskAmount / accountCurrencyProfitPerPip;

   return NormalizeDouble(stopLossPips, 0); // Round to whole pips
  }

//+------------------------------------------------------------------+
//| Function to calculate lot size based on risk.                   |
//+------------------------------------------------------------------+
double CalculateLotSize(string symbol, double riskPercentage)
  {
   double balance = AccountInfoDouble(ACCOUNT_BALANCE);
   double stopLossPips = CalculateStopLossPips(symbol, riskPercentage);
   double tickValue;
   double tickSize;
   double pointValue;


   //--- Get the market information for the symbol
   tickSize  = MarketInfo(symbol,MODE_TICKSIZE);
   tickValue = MarketInfo(symbol,MODE_TICKVALUE);
   pointValue = Point();

   //--- Calculate the maximum riskable amount in the account currency
   double riskAmount = balance * riskPercentage;

   //--- Calculate lot size
   double lotSize = riskAmount / (stopLossPips * pointValue * MarketInfo(symbol, MODE_TICKVALUE)); // corrected

   //--- Normalize lot size to the allowed minimum and step size.
   lotSize = NormalizeDouble(lotSize,1);
   lotSize = MathMax(MarketInfo(symbol, MODE_MINLOT), MathMin(lotSize, MarketInfo(symbol, MODE_MAXLOT)));

   return lotSize;
  }

//+------------------------------------------------------------------+
//| Check if trading is allowed                                      |
//+------------------------------------------------------------------+
bool IsTradeAllowed()
{
   //--- Check if trading is generally allowed in settings
   if(!TerminalInfoInteger(TERMINAL_TRADE))
      return false;

   //--- Check if trading is allowed by the account
   if(!AccountInfoInteger(ACCOUNT_TRADE_ALLOWED))
      return false;

   //Additional checks can be added here, e.g.
   //- check if trading is allowed based on the symbol's trading session
   //- check if the EA is allowed to trade by the user
   //These depend on the specifics and require more code

   return true;
}
//+------------------------------------------------------------------+
```

